#!/usr/bin/env bash
# lib/bazarr.sh — Bazarr subtitle service configuration helpers.

# Write only the small, deterministic part of Bazarr's configuration that the
# installer owns. Provider credentials, language profiles and other user
# preferences remain in Bazarr's config untouched.
generate_bazarr_config() {
    local config_file="${CONFIG_DIR}/bazarr/config.yaml"
    if [[ -f "$config_file" ]]; then
        log_info "Preserving existing Bazarr configuration."
        return 0
    fi

    cat >"$config_file" <<BAZARR_YAML
# Generated by TorBox Media Server. Configure providers and language profiles
# in the Bazarr web UI after installation.
general:
  ip: "*"
  port: 6767
  use_sonarr: true
  use_radarr: true
  path_mappings: []
  path_mappings_movie: []
auth:
  apikey: "${BAZARR_API_KEY}"
sonarr:
  ip: "sonarr"
  port: 8989
  base_url: "/"
  ssl: false
  apikey: "${SONARR_API_KEY}"
radarr:
  ip: "radarr"
  port: 7878
  base_url: "/"
  ssl: false
  apikey: "${RADARR_API_KEY}"
BAZARR_YAML
    chmod 600 "$config_file"
    log_info "Bazarr configuration written with Sonarr/Radarr connections pre-seeded."
}

# Apply the same connections through Bazarr's API after the service starts.
# The endpoint updates only the Sonarr/Radarr fields listed below; provider
# credentials, language profiles and other existing settings are retained.
configure_bazarr() {
    local url="${1:-http://localhost:6767}"
    local api_key="${BAZARR_API_KEY:-}"
    local elapsed=0

    if [[ -z "$api_key" ]]; then
        log_warn "Bazarr API key is unavailable; configure Bazarr manually at ${url}."
        return 1
    fi

    log_step "Waiting for Bazarr to be ready..."
    while [[ $elapsed -lt 120 ]]; do
        if curl -sf --connect-timeout 3 --max-time 10 \
            -H "X-API-KEY: ${api_key}" \
            "${url}/api/system/status?apikey=${api_key}" -o /dev/null 2>/dev/null; then
            break
        fi
        sleep 3
        elapsed=$((elapsed + 3))
    done
    if [[ $elapsed -ge 120 ]]; then
        log_warn "Bazarr did not become ready within 120s. Configure it manually at ${url}."
        return 1
    fi

    if curl -sf --connect-timeout 5 --max-time 20 \
        -X POST \
        -H "X-API-KEY: ${api_key}" \
        "${url}/api/system/settings?apikey=${api_key}" \
        --data-urlencode "settings-general-use_sonarr=true" \
        --data-urlencode "settings-general-use_radarr=true" \
        --data-urlencode "settings-sonarr-ip=sonarr" \
        --data-urlencode "settings-sonarr-port=8989" \
        --data-urlencode "settings-sonarr-base_url=/" \
        --data-urlencode "settings-sonarr-ssl=false" \
        --data-urlencode "settings-sonarr-apikey=${SONARR_API_KEY}" \
        --data-urlencode "settings-radarr-ip=radarr" \
        --data-urlencode "settings-radarr-port=7878" \
        --data-urlencode "settings-radarr-base_url=/" \
        --data-urlencode "settings-radarr-ssl=false" \
        --data-urlencode "settings-radarr-apikey=${RADARR_API_KEY}" \
        -o /dev/null 2>/dev/null; then
        log_info "Bazarr connected to Sonarr and Radarr."
        return 0
    fi

    log_warn "Bazarr is running but its API connection setup was not accepted. Check ${url}/config."
    return 1
}
